from functools import reduce
from copy import copy

import numpy as np
#from numpy.polynomial.legendre import leggauss
from mpmath import mp, mpf

from .helpers import safe_numeric_to_numpy

leggauss_rules = {}
def compute_leggauss(deg):
    if deg not in leggauss_rules:
        x,w = mp.gauss_quadrature(int(deg), "legendre")
        x = [(c+1.0)/2.0 for c in x]
        w = [c/2.0 for c in w]
        x_np = safe_numeric_to_numpy(x)
        w_np = safe_numeric_to_numpy(w)
        leggauss_rules[deg] = ((x,w),(x_np, w_np))
    return leggauss_rules[deg]

# Method generated by OpenAI Astra 6.0 Max
def element_gauss_legendre_np(lp, ext, deg, scale):
    """
    lp, ext: arrays of shape (k, d).
        Lower corners and nonnegative side lengths.
    deg: integer array of shape (k, d).
        deg[i, j] is the number of nodes for box i along axis j.

    Returns shape (sum_i prod_j deg[i, j], d + 1):
        [x_0, ..., x_{d-1}, weight], grouped by box.
    """

    d = lp.shape[1]

    # Compute each distinct 1D rule on [0, 1] only once.
    rules = {}
    for n in np.unique(deg):
        rules[int(n)] = compute_leggauss(int(n))[1]

    blocks = []
    for lower, size, orders in zip(lp, ext, deg):
        nodes, weights = zip(*(rules[int(n)] for n in orders))

        # Tensor-product nodes; last coordinate varies fastest.
        grid = np.stack(
            np.meshgrid(*nodes, indexing="ij"), axis=-1
        ).reshape(-1, d)

        # Tensor-product weights, flattened in the same order.
        tensor_weights = reduce(np.multiply.outer, weights).ravel()

        # Map to the box and multiply by its volume.
        points = lower + size * grid
        box_weights = np.prod(size) * tensor_weights

        blocks.append(np.column_stack((points, box_weights)))

    nodes_weights = np.concatenate(blocks, axis=0) if blocks else np.empty((0, d + 1))
    return nodes_weights[:,:-1], scale * nodes_weights[:,-1]

# Nonvectorized equivalent of "element_gauss_legendre_np" intended for use with mpmath
def element_gauss_legendre_high_prec(lp, ext, deg, scale):
    d = len(lp[0])
    points = []
    weights = []
    def tensor_iteration(i, j, accumulated_point, accumulated_weight):
        for k in range(deg[i][j]):
            node = lp[i][j] + ext[i][j]*compute_leggauss(deg[i][j])[0][0][k]
            weight = ext[i][j]*compute_leggauss(deg[i][j])[0][1][k]
            accumulated_point.append(node)
            if j == (d-1):
                points.append(copy(accumulated_point))
                weights.append(scale * accumulated_weight * weight)
            else:
                tensor_iteration(i,j+1, accumulated_point, weight * accumulated_weight)
            accumulated_point.pop()

    for i in range(len(lp)):
        tensor_iteration(i, 0, [], mpf("1"))
    
    return points, weights

        

def element_gauss_legendre(lp, ext, deg, scale):
    if isinstance(lp, np.ndarray):
        return element_gauss_legendre_np(lp, ext, deg, scale)
    else:
        return element_gauss_legendre_high_prec(lp, ext, deg, scale)